// ─── 活终端：复刻真实 hudo 安装输出的循环演示 ───
// 行类型: cmd=命令行 dim=灰注 step=步骤 get=下载 bar=进度条 ok=成功 env=环境变量 box=汇总框
const termLines = ref([
  { k: 'cmd',  t: 'hudo setup' },
  { k: 'dim',  t: '已选择 3 个工具: Git, Node.js, VS Code' },
  { k: 'step', t: '[1/3] 安装 Git' },
  { k: 'bar',  t: 'Git-2.53.0-64-bit.exe' },
  { k: 'ok',   t: '✓ Git 2.53.0 安装完成' },
  { k: 'env',  t: 'PATH += D:\\hudo\\tools\\git\\cmd' },
  { k: 'step', t: '[2/3] 安装 Node.js' },
  { k: 'bar',  t: 'node-v24.18.0-win-x64.zip' },
  { k: 'ok',   t: '✓ Node.js v24.18.0 安装完成' },
  { k: 'env',  t: 'PATH += D:\\hudo\\lang\\node' },
  { k: 'step', t: '[3/3] 安装 VS Code' },
  { k: 'bar',  t: 'vscode-win32-x64.zip' },
  { k: 'ok',   t: '✓ VS Code 1.130.0 安装完成' },
  { k: 'env',  t: 'PATH += D:\\hudo\\ide\\vscode\\bin' },
  { k: 'sum',  t: '✓ 3 个工具安装完成 · 全程未弹出 UAC' },
])
const termVisible = ref(0)
const termRun = ref(0)
const typing = ref(false)
const termFading = ref(false)
let termTimer = null
let reduceMotion = false
function runTerm() {
  // 减弱动效：一次性静态展示完整成功输出（信息量最大的一帧），不循环
  if (reduceMotion) {
    termVisible.value = termLines.value.length
    typing.value = false
    return
  }
  if (typing.value) return
  typing.value = true
  termVisible.value = 0
  termFading.value = false
  const step = () => {
    if (termVisible.value < termLines.value.length) {
      const next = termLines.value[termVisible.value]
      termVisible.value++
      // 进度条行播完动画再走下一行；步骤行稍作停顿；其余匀速
      const delay = next.k === 'bar' ? 1050 : next.k === 'step' ? 320 : 190
      termTimer = setTimeout(step, delay)
    } else {
      typing.value = false
      // 结论帧多停留，淡出后再清屏重播（避免空白硬切）
      termTimer = setTimeout(() => {
        termFading.value = true
        termTimer = setTimeout(() => { termRun.value++; runTerm() }, 260)
      }, 6000)
    }
  }
  step()
}
function pauseTerm() {
  clearTimeout(termTimer)
  typing.value = false
}

// ─── Tilt on tool cards ───
function onTilt(e) {
  const el = e.currentTarget
  const r = el.getBoundingClientRect()
  const x = (e.clientX - r.left) / r.width - 0.5
  const y = (e.clientY - r.top) / r.height - 0.5
  el.style.setProperty('--rx', `${(-y * 8).toFixed(2)}deg`)
  el.style.setProperty('--ry', `${(x * 10).toFixed(2)}deg`)
  el.style.setProperty('--mx', `${(e.clientX - r.left).toFixed(0)}px`)
  el.style.setProperty('--my', `${(e.clientY - r.top).toFixed(0)}px`)
}
function offTilt(e) {
  const el = e.currentTarget
  el.style.setProperty('--rx', '0deg')
  el.style.setProperty('--ry', '0deg')
}

// ─── Spotlight on feature cards ───
function onSpot(e) {
  const el = e.currentTarget
  const r = el.getBoundingClientRect()
  el.style.setProperty('--mx', `${e.clientX - r.left}px`)
  el.style.setProperty('--my', `${e.clientY - r.top}px`)
}

// ─── Custom cursor + magnet ───
let cx = 0, cy = 0, rx = 0, ry = 0, rafId = 0
function moveCursor(e) {
  cx = e.clientX; cy = e.clientY
  if (cursorDot.value) {
    cursorDot.value.style.transform = `translate3d(${cx}px, ${cy}px, 0)`
  }
  // 背景网格鼠标高亮共用同一坐标（fixed 层，clientX/Y 即可）
  if (root.value) {
    root.value.style.setProperty('--gx', `${cx}px`)
    root.value.style.setProperty('--gy', `${cy}px`)
  }
}
function tickRing() {
  rx += (cx - rx) * 0.18
  ry += (cy - ry) * 0.18
  if (cursorRing.value) {
    cursorRing.value.style.transform = `translate3d(${rx}px, ${ry}px, 0)`
  }
  rafId = requestAnimationFrame(tickRing)
}

let io = null
let termIO = null
let termStarted = false
onMounted(async () => {
  await nextTick()

  reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches

  // cursor (desktop only；减弱动效时光标已由 CSS 隐藏，监听纯浪费)
  const canHover = window.matchMedia('(hover: hover)').matches
  if (canHover && !reduceMotion) {
    document.body.classList.add('cursor-on')
    window.addEventListener('mousemove', moveCursor, { passive: true })
    tickRing()
    // magnet hover
    document.querySelectorAll('[data-magnet]').forEach(el => {
      el.addEventListener('mouseenter', () => document.body.classList.add('cursor-hover'))
      el.addEventListener('mouseleave', () => document.body.classList.remove('cursor-hover'))
    })
  }

  // scroll reveal
  io = new IntersectionObserver((entries) => {
    entries.forEach(en => {
      if (en.isIntersecting) {
        en.target.classList.add('in')
        if (en.target.hasAttribute('data-reveal-group')) {
          en.target.querySelectorAll(':scope > *').forEach((c, i) => {
            c.style.setProperty('--d', `${i * 0.04}s`)
            c.classList.add('in')
          })
        }
        io.unobserve(en.target)
      }
    })
  }, { rootMargin: '0px 0px -10% 0px', threshold: 0.12 })

  document.querySelectorAll('[data-reveal], [data-reveal-group]').forEach(el => io.observe(el))

  // 终端循环用常驻 observer：首轮等入场动画完成再开拍；离开视口暂停，重入从头播
  if (reduceMotion) {
    termVisible.value = termLines.value.length
  } else if (termWrap.value) {
    termIO = new IntersectionObserver((entries) => {
      entries.forEach(en => {
        if (en.isIntersecting) {
          if (!termStarted) {
            termStarted = true
            termTimer = setTimeout(runTerm, 900)
          } else if (!typing.value) {
            runTerm()
          }
        } else {
          pauseTerm()
        }
      })
    }, { threshold: 0.1 })
    termIO.observe(termWrap.value)
  }
})

onUnmounted(() => {
  window.removeEventListener('mousemove', moveCursor)
  if (rafId) cancelAnimationFrame(rafId)
  if (io) io.disconnect()
  if (termIO) termIO.disconnect()
  if (termTimer) clearTimeout(termTimer)
  document.body.classList.remove('cursor-on', 'cursor-hover')
})
</script>

