              transform .9s cubic-bezier(.2,.7,.1,1) var(--d, 0s);
}
/* .in 规则同样带门控前缀：否则隐藏规则(多一个 html 类型选择器)优先级更高，.in 永远赢不了 */
:global(html.js) [data-reveal].in { opacity: 1; transform: none; }

:global(html.js) [data-reveal-group] > * {
  opacity: 0;
  transform: translateY(16px) scale(.98);
  transition: opacity .7s cubic-bezier(.2,.7,.1,1) var(--d, 0s),
              transform .7s cubic-bezier(.2,.7,.1,1) var(--d, 0s);
}
:global(html.js) [data-reveal-group] > *.in { opacity: 1; transform: none; }

/* headline line reveal */
.line {
  display: block;
  overflow: hidden;
}
:global(html.js) .line .fill {
  display: inline-block;
  transform: translateY(100%);
  transition: transform 1.1s cubic-bezier(.2,.7,.1,1) var(--d, 0s);
}
:global(html.js) .line.in .fill { transform: none; }
.line.in .fill:nth-child(2) { transition-delay: calc(var(--d) + .08s); }
.line.in .fill:nth-child(3) { transition-delay: calc(var(--d) + .16s); }
.line.in .fill:nth-child(4) { transition-delay: calc(var(--d) + .24s); }

/* ───────────── hero ───────────── */
.hero {
  position: relative;
  z-index: 1;
  padding: 130px 0 72px;
  min-height: 92vh;
  display: flex;
  align-items: center;
  text-align: center;
}
.hero .wrap { width: 100%; }

.badge {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 6px 14px 6px 10px;
  margin-bottom: 40px;
  font-size: .78rem;
  font-weight: 500;
  letter-spacing: .01em;
  color: var(--text-dim);
  background: var(--vp-c-bg-soft);
  border: 1px solid var(--line);
  border-radius: 100px;
  backdrop-filter: blur(10px);
  text-decoration: none;
  transition: border-color .25s, color .25s;
}
.badge:hover { border-color: var(--brand); color: var(--vp-c-text-1); }
.badge-dot {
  width: 6px; height: 6px;
  border-radius: 50%;
  background: #10b981;
  box-shadow: 0 0 0 0 rgba(16,185,129,.6);
  animation: pulse 2.2s ease-out infinite;
}
@keyframes pulse {
  0%   { box-shadow: 0 0 0 0 rgba(16,185,129,.6); }
  70%  { box-shadow: 0 0 0 10px rgba(16,185,129,0); }
  100% { box-shadow: 0 0 0 0 rgba(16,185,129,0); }
}
.badge-arrow { color: var(--brand); font-weight: 700; }

.headline {
  font-size: clamp(2.6rem, 7.2vw, 6rem);
  font-weight: 800;
  line-height: .98;
  letter-spacing: -0.045em;
  margin: 0 0 28px;
  color: var(--vp-c-text-1);
  /* 中文词组（如"开发环境"）不许被劈开留孤字 */
  word-break: keep-all;
}
.gradient {
  background: linear-gradient(135deg, #60a5fa 0%, #a78bfa 50%, #f472b6 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}
/* 亮色主题用更深的品牌渐变，白底上对比度才够 */
:root:not(.dark) .gradient {
  background: linear-gradient(135deg, #2563eb 0%, #7c3aed 50%, #db2777 100%);
  -webkit-background-clip: text;
  background-clip: text;
}
.dot { color: var(--brand); }

.sub {
  max-width: 620px;
  margin: 0 auto 40px;
  font-size: clamp(.98rem, 1.3vw, 1.15rem);
  line-height: 1.7;
  color: var(--text-dim);
}
.md-only { display: none; }
@media (min-width: 640px) { .md-only { display: inline; } }

/* install box */
.install-row {
  display: flex;
  justify-content: center;
  margin-bottom: 28px;
}
.install {
  position: relative;
  display: inline-flex;
  align-items: center;
  max-width: 100%;
  gap: 14px;
  padding: 14px 8px 14px 20px;
  background: var(--vp-c-bg-soft);
  border: 1px solid var(--line);
  border-radius: 14px;
  font-family: 'JetBrains Mono', 'Cascadia Code', monospace;
  font-size: .88rem;
  cursor: pointer;
  overflow: hidden;
  transition: border-color .3s;
  /* button 化后的外观重置 */
  appearance: none;
  font: inherit;
  font-family: 'JetBrains Mono', 'Cascadia Code', monospace;
  text-align: inherit;
  color: inherit;
}
.install:hover { border-color: rgba(96,165,250,.4); }
/* 键盘焦点可见（自定义光标不服务键盘用户） */
.install:focus-visible,
.btn:focus-visible {
  outline: 2px solid var(--brand);
  outline-offset: 3px;
}
/* 旋转的是渐变角度而非元素几何：元素 rotate 会让描边层扫过内容造成穿模；
   节奏为扫一圈后静止（把持续注意力让给活终端）；不支持 @property 的浏览器退化为静态描边 */
@property --ang {
  syntax: '<angle>';
  inherits: false;
  initial-value: 0deg;
}
.i-gradient {
  position: absolute;
  inset: -1px;
  border-radius: 14px;
  padding: 1px;
  background: conic-gradient(from var(--ang), transparent 0%, rgba(96,165,250,.8) 20%, rgba(167,139,250,.7) 40%, rgba(244,114,182,.6) 50%, transparent 70%);
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  animation: spin 8s ease-in-out infinite;
  opacity: .8;
}
@keyframes spin {
  0%   { --ang: 0deg; }
  35%  { --ang: 1turn; }
  100% { --ang: 1turn; }
}

.i-prompt { color: var(--brand-2); font-weight: 700; user-select: none; }
.i-cmd { color: var(--vp-c-text-1); font-weight: 500; }
.i-action {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  border-radius: 8px;
  font-size: .75rem;
  font-weight: 600;
  color: var(--text-dim);
  background: var(--vp-c-bg);
  border: 1px solid var(--line);
  transition: all .15s;
}
.install:hover .i-action { color: var(--vp-c-text-1); border-color: var(--text-dim); }
.install.copied .i-action { color: #10b981; border-color: rgba(16,185,129,.4); }
.i-label { font-family: var(--vp-font-family-base); letter-spacing: .02em; }

/* 终端风格数据行 */
.stat-row {
  display: flex;
  justify-content: center;
  align-items: baseline;
  gap: 14px;
  margin-bottom: 26px;
  font-family: 'JetBrains Mono', 'Cascadia Code', monospace;
  font-size: .82rem;
  color: var(--text-dim);
}
.stat-key { color: var(--brand); }
.stat-val { color: var(--vp-c-text-1); font-weight: 700; }
.stat-sep { opacity: .35; }

/* buttons */
.cta-row {
  display: flex;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 56px;
}
.btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 0 22px;
  height: 46px;
  border-radius: 10px;
  font-size: .92rem;
  font-weight: 600;
  letter-spacing: .005em;
  text-decoration: none;
  transition: transform .25s cubic-bezier(.2,.7,.1,1), box-shadow .25s, background .2s, border-color .2s, color .2s;
  overflow: hidden;
  border: 1px solid transparent;
}
.btn.lg { height: 52px; padding: 0 28px; font-size: 1rem; }
.btn:hover { transform: translateY(-1px); }

.btn.primary {
  background: linear-gradient(180deg, #fff, #e8eaef);
  color: #0a0a0f;
}
.dark .btn.primary { background: linear-gradient(180deg, #fff, #d9dde4); }
.btn.primary:hover {
  box-shadow: 0 8px 28px -8px rgba(255,255,255,.3), 0 0 0 1px rgba(255,255,255,.2);
}
:root:not(.dark) .btn.primary {
  background: linear-gradient(180deg, #0f172a, #1e293b);
  color: #fff;
}
:root:not(.dark) .btn.primary:hover {
  box-shadow: 0 8px 28px -8px rgba(15,23,42,.5);
}

/* 次级按钮：填充色块（不用描边/幽灵按钮） */
.btn.solid {
  background: #1e2637;
  color: #e2e8f0;
}
.btn.solid:hover { background: #273044; box-shadow: 0 8px 24px -10px rgba(96,165,250,.35); }
:root:not(.dark) .btn.solid {
  background: #e2e8f0;
  color: #0f172a;
}
:root:not(.dark) .btn.solid:hover { background: #d3dae4; box-shadow: 0 8px 24px -10px rgba(15,23,42,.3); }
.star-count {
  padding-left: 10px;
  margin-left: 2px;
  border-left: 1px solid rgba(148,163,184,.35);
  color: inherit;
  opacity: .75;
  font-size: .78rem;
  font-weight: 500;
}

/* hero 内嵌活终端 */
.hero-term {
  margin-top: 8px;
  text-align: left;
}

/* ───────────── marquee ───────────── */
.marquee {
  position: relative;
  z-index: 1;
  padding: 24px 0;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  overflow: hidden;
  background: var(--vp-c-bg-soft);
  mask-image: linear-gradient(90deg, transparent, #000 10%, #000 90%, transparent);
  -webkit-mask-image: linear-gradient(90deg, transparent, #000 10%, #000 90%, transparent);
}
.mq-track {
  display: flex;
  gap: 56px;
  animation: marquee 60s linear infinite;
  width: max-content;
  font-family: 'JetBrains Mono', monospace;
  font-size: .82rem;
  font-weight: 500;
  color: var(--text-dim);
  letter-spacing: .03em;
}
.mq-item { display: inline-flex; align-items: center; gap: 16px; white-space: nowrap; }
.mq-bullet { color: var(--brand); }
@keyframes marquee {
  from { transform: translateX(0); }
  to   { transform: translateX(-50%); }
}

/* ───────────── generic section ───────────── */
.sec {
  position: relative;
  z-index: 1;
  padding: 120px 0;
}
.sec-head { text-align: center; margin-bottom: 56px; max-width: 720px; margin-left: auto; margin-right: auto; }
.sec-label {
  display: inline-block;
  margin-bottom: 20px;
  font-family: 'JetBrains Mono', monospace;
  font-size: .8rem;
  font-weight: 500;
  letter-spacing: .08em;
  color: var(--brand);
}
.sec-title {
  font-size: clamp(1.8rem, 4vw, 3rem);
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: -0.03em;
  margin: 0 0 16px;
}
.sec-desc { font-size: 1.02rem; color: var(--text-dim); line-height: 1.65; margin: 0; }

/* ───────────── tools grid ───────────── */
.tools-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 14px;
  perspective: 1000px;
}
.tool {
  position: relative;
  aspect-ratio: 1.3;
  transform-style: preserve-3d;
  transform: perspective(600px) rotateX(var(--rx, 0deg)) rotateY(var(--ry, 0deg));
  transition: transform .2s cubic-bezier(.2,.7,.1,1);
  cursor: pointer;
}
.tool-inner {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 18px 10px;
  background: var(--vp-c-bg-soft);
  border: 1px solid var(--line);
  border-radius: 16px;
  overflow: hidden;
  transition: border-color .3s, background .3s;
}
.tool:hover .tool-inner {
  border-color: rgba(96,165,250,.35);
}
.tool-glow {
  position: absolute;
  inset: 0;
  opacity: 0;
  transition: opacity .3s;
  background: radial-gradient(280px circle at var(--mx) var(--my), rgba(96,165,250,.15), transparent 70%);
  pointer-events: none;
}
.tool:hover .tool-glow { opacity: 1; }
.tool-svg {
  width: 30px; height: 30px;
  display: flex; align-items: center; justify-content: center;
  transition: transform .35s cubic-bezier(.2,.7,.1,1);
}
.tool:hover .tool-svg { transform: scale(1.12) rotate(-4deg); }
.tool-svg :deep(svg) { width: 100%; height: 100%; }
.tool-name {
  font-size: .74rem;
  color: var(--text-dim);
  font-weight: 500;
  letter-spacing: .01em;
}

/* ───────────── features ───────────── */
.feat-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}
.feat {
  position: relative;
  padding: 1px;
  border-radius: 20px;
  overflow: hidden;
  transition: transform .4s cubic-bezier(.2,.7,.1,1);
  background: var(--line);
}
.feat:hover { transform: translateY(-4px); }
.feat-border {
  position: absolute;
  inset: 0;
  border-radius: 20px;
  opacity: 0;
  transition: opacity .35s;
  background: conic-gradient(from 0deg at var(--mx, 50%) var(--my, 50%), transparent 0deg, var(--brand) 90deg, var(--brand-2) 180deg, var(--brand-3) 270deg, transparent 360deg);
  pointer-events: none;
}
.feat:hover .feat-border { opacity: .8; }
.feat-spot {
  position: absolute;
  inset: 1px;
  border-radius: 19px;
  background: radial-gradient(400px circle at var(--mx) var(--my), rgba(96,165,250,.1), transparent 40%);
  opacity: 0;
  transition: opacity .3s;
  pointer-events: none;
}
.feat:hover .feat-spot { opacity: 1; }
.feat-body {
  position: relative;
  height: 100%;
  padding: 32px 28px;
  background: var(--vp-c-bg);
  border-radius: 19px;
}
.feat-icon {
  width: 40px; height: 40px;
  display: flex; align-items: center; justify-content: center;
  margin-bottom: 20px;
  border-radius: 10px;
  background: linear-gradient(135deg, rgba(96,165,250,.12), rgba(167,139,250,.08));
  color: var(--brand);
}
.feat-title {
  font-size: 1.08rem;
  font-weight: 600;
  margin: 0 0 10px;
  letter-spacing: -0.01em;
}
.feat-desc {
  font-size: .9rem;
  line-height: 1.65;
  color: var(--text-dim);
  margin: 0;
}
.feat-arrow {
  position: absolute;
  top: 28px; right: 24px;
  width: 32px; height: 32px;
  display: flex; align-items: center; justify-content: center;
  border-radius: 50%;
  color: var(--text-dim);
  opacity: 0;
  transform: translate(-6px, 6px) rotate(-45deg);
  transition: opacity .3s, transform .3s;
}
.feat:hover .feat-arrow {
  opacity: 1;
  transform: translate(0,0) rotate(-45deg);
  color: var(--brand);
}

/* ───────────── terminal ───────────── */
.term-wrap {
  max-width: 760px;
  margin: 0 auto;
  position: relative;
}
.term-glow {
  position: absolute;
  inset: -60px;
  background: radial-gradient(ellipse at center, rgba(96,165,250,.18), rgba(167,139,250,.08) 40%, transparent 70%);
  filter: blur(40px);
  pointer-events: none;
  z-index: 0;
}
.term {
  position: relative;
  z-index: 1;
  background: #06080f;
  border: 1px solid #1a1d2b;
  border-radius: 16px;
  overflow: hidden;
  box-shadow:
    0 0 0 1px rgba(255,255,255,.03),
    0 30px 80px -20px rgba(0,0,0,.6),
    0 0 100px -30px rgba(96,165,250,.15);
  font-family: 'JetBrains Mono', monospace;
}
.term-bar {
  display: flex;
  align-items: center;
  padding: 14px 18px;
  background: #0b0e18;
  border-bottom: 1px solid #1a1d2b;
}
.term-dots { display: flex; gap: 7px; }
.term-dots span {
  width: 11px; height: 11px;
  border-radius: 50%;
}
.term-dots span:nth-child(1) { background: #ff5f57; }
.term-dots span:nth-child(2) { background: #ffbd2e; }
.term-dots span:nth-child(3) { background: #28c840; }
.term-title {
  flex: 1;
  text-align: center;
  font-size: .72rem;
  color: #6b7288;
  font-family: var(--vp-font-family-base);
  letter-spacing: .02em;
}
.term-spacer { width: 52px; }

.term-body {
  padding: 22px 26px;
  min-height: 420px;
  color: #c9d1d9;
  font-size: .84rem;
  line-height: 1.75;
  transition: opacity .25s ease;
}
.term-body.fading { opacity: 0; }
.tl {
  display: flex;
  align-items: center;
  gap: 10px;
  animation: tlIn .25s ease-out;
  /* flex 项默认 min-width:auto，nowrap 的进度条文件名会撑破终端并推宽整页 */
  min-width: 0;
}
.tl-text { min-width: 0; overflow-wrap: anywhere; }
@keyframes tlIn {
  from { opacity: 0; transform: translateY(5px); }
  to   { opacity: 1; transform: none; }
}
.tl-prompt { color: #a78bfa; font-weight: 600; white-space: nowrap; }
.tl.cmd .tl-text  { color: #e2e8f0; font-weight: 600; }
.tl.dim .tl-text  { color: #8b95ab; }
.tl.step .tl-text { color: #60a5fa; font-weight: 700; margin-top: 4px; }
.tl.ok .tl-text   { color: #34d399; }
.tl.env .tl-text  { color: #8b95ab; }
.tl.sum { margin-top: 14px; }
.tl.sum .tl-text {
  color: #34d399;
  border: 1px solid rgba(52,211,153,.35);
  border-radius: 8px;
  padding: 8px 16px;
  background: rgba(52,211,153,.06);
}
.caret {
  display: inline-block;
  width: 8px;
  color: #60a5fa;
  animation: blink 1s step-end infinite;
}
@keyframes blink { 50% { opacity: 0; } }

/* 行内下载进度条：每次出现从 0 冲到 100% */
.tl.bar { padding-left: 18px; }
.tl-bar-track {
  width: 42%;
  max-width: 300px;
  height: 4px;
  background: #141725;
  border-radius: 3px;
  overflow: hidden;
  flex: none;
}
.tl-bar-fill {
  width: 0;
  height: 100%;
  background: linear-gradient(90deg, #60a5fa, #a78bfa, #f472b6);
  border-radius: 3px;
  animation: fill .9s cubic-bezier(.25,.6,.3,1) forwards;
}
@keyframes fill {
  from { width: 0; }
  to   { width: 100%; }
}
.tl-bar-text {
  flex: 1;
  min-width: 0;
  font-size: .72rem;
  color: #8b95ab;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ───────────── CTA ───────────── */
.cta-sec { padding: 60px 0 140px; }
.cta {
  position: relative;
  padding: 88px 40px;
  text-align: center;
  background: var(--vp-c-bg-soft);
  border: 1px solid var(--line);
  border-radius: 24px;
  overflow: hidden;
}
.cta-beam {
  position: absolute;
  top: 0; left: -65%;
  width: 60%;
  height: 2px;
  background: linear-gradient(90deg, transparent, var(--brand), transparent);
  animation: beamSweep 8s ease-in-out infinite;
}
/* 起始帧整条在卡片外（含亮心），扫过后停顿，避免凭空闪现 */
@keyframes beamSweep {
  0%, 12% { transform: translateX(0); }
  55%     { transform: translateX(300%); }
  100%    { transform: translateX(300%); }
}
.cta-grid {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(var(--line) 1px, transparent 1px),
    linear-gradient(90deg, var(--line) 1px, transparent 1px);
  background-size: 40px 40px;
  mask-image: radial-gradient(ellipse 60% 80% at 50% 50%, #000, transparent);
  -webkit-mask-image: radial-gradient(ellipse 60% 80% at 50% 50%, #000, transparent);
  opacity: .6;
}
.cta-label {
  position: relative;
  font-family: 'JetBrains Mono', monospace;
  font-size: .8rem;
  color: var(--brand);
  margin: 0 0 16px;
  letter-spacing: .06em;
}
.cta-title {
  position: relative;
  font-size: clamp(1.6rem, 3vw, 2.4rem);
  font-weight: 700;
  line-height: 1.25;
  letter-spacing: -0.02em;
  margin: 0 0 36px;
}
.cta-btns {
  position: relative;
  display: flex;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
}

/* ───────────── responsive ───────────── */
@media (max-width: 960px) {
  .tools-grid { grid-template-columns: repeat(4, 1fr); }
  .feat-grid  { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 640px) {
  .wrap { padding: 0 20px; }
  .hero { padding: 110px 0 60px; min-height: auto; }
  .headline { letter-spacing: -0.03em; font-size: clamp(2.15rem, 10vw, 2.6rem); }
  /* 命令必须单行完整可见：Copy 只留图标，字号随视口收缩保证 34 字符恰好放下 */
  .install { font-size: min(.78rem, 2.9vw); padding: 12px 6px 12px 12px; gap: 8px; }
  .i-action { padding: 5px 8px; }
  .i-label { display: none; }
  .i-cmd { white-space: nowrap; }
  .stat-row { flex-wrap: wrap; gap: 8px; font-size: .74rem; }
  .cta-row { margin-bottom: 40px; }
  .term-body { min-height: 380px; font-size: .74rem; padding: 16px 14px; }
  .tl.bar { padding-left: 10px; }
  .tl-bar-track { width: 34%; }
  .tools-grid { grid-template-columns: repeat(3, 1fr); gap: 10px; }
  .tool { aspect-ratio: 1.15; }
  .feat-grid  { grid-template-columns: 1fr; }
  .feat-body  { padding: 28px 24px; }
  .sec { padding: 80px 0; }
  .cta { padding: 56px 24px; }
}

